package com.wanyuecity.energy.stall.service;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.wanyuecity.energy.core.BizException;
import com.wanyuecity.energy.stall.entity.*;
import com.wanyuecity.energy.stall.mapper.*;
import com.wanyuecity.energy.stall.service.dto.*;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.BeanUtils;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service @RequiredArgsConstructor
public class StallEngineeringService {
    private final StallMapper stallMapper; private final StallEngineeringProfileMapper mapper;
    public StallEngineeringView get(Long stallId){Stall stall=requireStall(stallId);StallEngineeringProfile profile=mapper.selectOne(new LambdaQueryWrapper<StallEngineeringProfile>().eq(StallEngineeringProfile::getStallId,stallId).last("LIMIT 1"));if(profile==null){profile=new StallEngineeringProfile();profile.setStallId(stallId);defaults(profile);}return view(stall,profile);}
    @Transactional public StallEngineeringView save(Long stallId,StallEngineeringRequest req){Stall stall=requireStall(stallId);validateConditional(req);StallEngineeringProfile row=mapper.selectOne(new LambdaQueryWrapper<StallEngineeringProfile>().eq(StallEngineeringProfile::getStallId,stallId).last("LIMIT 1"));boolean create=row==null;if(create){row=new StallEngineeringProfile();row.setStallId(stallId);}BeanUtils.copyProperties(req,row);defaults(row);clearDisabled(row);if(create)mapper.insert(row);else mapper.updateById(row);return view(stall,row);}
    private Stall requireStall(Long id){Stall s=stallMapper.selectById(id);if(s==null)throw BizException.notFound("铺位不存在");return s;}
    private void validateConditional(StallEngineeringRequest r){if(Boolean.TRUE.equals(r.getWaterSupply())&&blank(r.getWaterMeterCaliber()))throw BizException.badRequest("供水铺位必须填写水表口径");if(Boolean.TRUE.equals(r.getDrainageAvailable())&&blank(r.getDrainagePipeCaliber()))throw BizException.badRequest("有排水管时必须填写排水管口径");if(Boolean.TRUE.equals(r.getGasConnected())&&!Boolean.TRUE.equals(r.getGasConditionAvailable()))throw BizException.badRequest("已接通燃气时必须具备燃气条件");if(Boolean.TRUE.equals(r.getGasConnected())&&(blank(r.getGasType())||blank(r.getGasPipelineNo())))throw BizException.badRequest("已接通燃气时必须填写燃气类型和管道编号");if(Boolean.TRUE.equals(r.getGasAccepted())&&(r.getGasAcceptanceDate()==null||blank(r.getGasAcceptanceOrg())))throw BizException.badRequest("燃气已验收时必须填写验收日期和验收单位");}
    private void defaults(StallEngineeringProfile r){if(r.getCableQuantity()==null)r.setCableQuantity(0);if(r.getAirConditionerQuantity()==null)r.setAirConditionerQuantity(0);if(r.getFanCoilQuantity()==null)r.setFanCoilQuantity(0);if(r.getHangingCabinetQuantity()==null)r.setHangingCabinetQuantity(0);if(r.getAirOutletQuantity()==null)r.setAirOutletQuantity(0);if(r.getGasPipeQuantity()==null)r.setGasPipeQuantity(0);if(r.getGasAlarmQuantity()==null)r.setGasAlarmQuantity(0);if(r.getWaterSupply()==null)r.setWaterSupply(false);if(r.getDrainageAvailable()==null)r.setDrainageAvailable(false);if(r.getExhaustDuctAvailable()==null)r.setExhaustDuctAvailable(false);if(r.getFreshAirDuctAvailable()==null)r.setFreshAirDuctAvailable(false);if(r.getGasConditionAvailable()==null)r.setGasConditionAvailable(false);if(r.getGasConnected()==null)r.setGasConnected(false);if(r.getGasAlarm()==null)r.setGasAlarm(false);if(r.getAutoShutoffValve()==null)r.setAutoShutoffValve(false);if(r.getGasAccepted()==null)r.setGasAccepted(false);}
    private void clearDisabled(StallEngineeringProfile r){if(!r.getWaterSupply()){r.setWaterMeterCaliber(null);r.setWaterMeterLocation(null);}if(!r.getDrainageAvailable()){r.setDrainagePipeCaliber(null);r.setDrainagePipelineNo(null);}if(!r.getExhaustDuctAvailable())r.setExhaustDuctNo(null);if(!r.getFreshAirDuctAvailable())r.setFreshAirDuctNo(null);if(!r.getGasConditionAvailable()){r.setGasConnected(false);r.setGasType(null);r.setGasPipeQuantity(0);r.setGasPipeCaliber(null);r.setGasPipelineNo(null);r.setGasInterfaceLocation(null);r.setGasMeterNo(null);r.setGasMeterModel(null);r.setGasMeterLocation(null);r.setDesignGasFlow(null);r.setDesignGasLoadKw(null);r.setGasValveNo(null);r.setGasAlarm(false);r.setGasAlarmQuantity(0);r.setAutoShutoffValve(false);r.setGasAccepted(false);r.setGasAcceptanceDate(null);r.setGasAcceptanceOrg(null);}else if(!r.getGasConnected()){r.setGasMeterNo(null);r.setGasMeterModel(null);r.setGasMeterLocation(null);}if(!r.getGasAlarm())r.setGasAlarmQuantity(0);if(!r.getGasAccepted()){r.setGasAcceptanceDate(null);r.setGasAcceptanceOrg(null);}}
    private StallEngineeringView view(Stall s,StallEngineeringProfile p){StallEngineeringView v=new StallEngineeringView();v.setStallId(s.getId());v.setStallCode(s.getStallCode());v.setStallName(s.getStallName());v.setFloorCode(s.getFloorCode());v.setBusinessType(s.getBusinessType());v.setProfile(p);return v;}private boolean blank(String v){return v==null||v.isBlank();}
}
